function checkout(){
  function makeFire() {
    const fireGeometry = new THREE.SphereGeometry(0.5, 32, 32);
    const fireMaterial = new THREE.MeshStandardMaterial({
      color: 0xff4500,
      emissive: 0xff4500,
      emissiveIntensity: 1,
      roughness: 0.9,
      metalness: 0.1
    });
    const fire = new THREE.Mesh(fireGeometry, fireMaterial);
    fire.castShadow = true;
    fire.position.set(0, 0.5, 0);
    scene.add(fire);
  }
  makeFire();
  setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),2800);
}
